import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes2')
from h import *
X=[]
X.append(r(9523761,"Mermelada saludable de arándanos y chía - ¡baja en azúcar y sin pectina!","Deliciosa mermelada de arándanos y chía, endulzada naturalmente, con un toque ácido de limón.","16 porciones","1 porción",
["4 tazas de arándanos azules frescos o congelados y descongelados","1 cucharada de ralladura de limón (de aprox. 1 limón grande)","⅓ de taza de jugo de limón (de aprox. 1 limón grande, el mismo limón)","2 cucharadas de jarabe de arce, opcional","⅓ de taza de semillas de chía"],
["Agregue los arándanos, el jugo de limón, la ralladura y el jarabe de arce (si lo usa) a una olla mediana. Cocine a fuego medio durante unos 5 minutos. Notará que los arándanos empiezan a reventar.","Luego macháquelos suavemente con un machacador de papas o un tenedor grande hasta que aproximadamente la mitad de los arándanos estén machacados, dejando varios trozos.","Aumente el fuego y hierva durante 5 minutos para reducir parte del líquido. Luego apague el fuego e incorpore las semillas de chía.","Pase la mermelada de arándanos y chía a frascos limpios y secos, y refrigere o congele."],
["Necesita 1 limón grande para la ralladura y el jugo. Asegúrese de rallar el limón antes de exprimirlo. No machaque demasiado la mermelada hasta convertirla en puré. Algunos trozos de arándano le darán una buena textura. Si la mermelada se ve líquida después de hervir, no se preocupe. Las semillas de chía absorberán la mayor parte del exceso de líquido al enfriarse. Para una textura más suave (si no le gusta la textura de la chía), muela las semillas de chía antes de agregarlas a la mermelada. Pruébela con otras bayas como frambuesas y/o moras. O pruebe nuestra versión de fresa aquí. Guarde la mermelada en uno o más frascos de vidrio limpios en el refrigerador hasta por 2 semanas, o congélela hasta por 6 meses. Me gusta guardarla en 2 frascos distintos: uno para el refrigerador y otro para el congelador."],[]))
X.append(r(9529012,"Guisantes en freidora de aire (dos sabores)","Los guisantes en freidora de aire son una guarnición fantástica y llena de sabor que puede preparar en 10 minutos.","2 porciones","1 porción",
[("Sabor barbacoa","1 taza de guisantes congelados, descongelados"),("Sabor barbacoa","1 cucharadita de ajo en polvo"),("Sabor barbacoa","1 cucharadita de pimentón ahumado"),("Sabor barbacoa","sal + pimienta al gusto"),("Sabor italiano","1 taza de guisantes congelados, descongelados"),("Sabor italiano","1 cucharadita de ajo en polvo"),("Sabor italiano","1 cucharadita de condimento italiano"),("Sabor italiano","sal + pimienta al gusto")],
["Coloque los guisantes descongelados en un tazón pequeño y agregue el condimento de su elección. Mezcle bien y distribuya los guisantes en una sola capa en la canasta de la freidora de aire.","Cocine los guisantes en la freidora de aire a 350℉/176℃ durante 8-12 minutos, o hasta alcanzar el punto deseado. Mezcle o sacuda la canasta cada 2-3 minutos."],
["Distribuya los guisantes en una sola capa para que se cocinen de manera uniforme.","Sacuda la canasta o mezcle los guisantes cada 2-3 minutos para evitar que se peguen y/o se quemen."],[]))
X.append(r(9529996,"Galletas veganas de mantequilla de nuez pecana [sin aceite]","¡Increíbles galletas veganas de mantequilla de nuez pecana! Son húmedas, suaves y mantecosas, saladas y dulces a la vez, y ¡MUY, MUY buenas!","12 galletas","1 porción",
["1 taza de mantequilla de nuez pecana","⅓ de taza de azúcar de coco sin refinar o azúcar morena","½ cucharadita de polvo para hornear","1 cucharadita de vainilla, opcional pero recomendada","1 cucharadita de canela, opcional pero recomendada","¼ de cucharadita de sal marina, opcional pero recomendada","1-2 cucharadas de leche de nuez de la India (anacardo) sin azúcar o la leche de su elección"],
["Precaliente el horno a 350 grados F y forre una bandeja grande para hornear con papel pergamino.","En un tazón mediano, agregue todos los ingredientes, empezando con solo 1 cucharada de leche, y mezcle bien. La masa debe quedar espesa y pegajosa. Si le parece demasiado seca para mantenerse unida, agregue la segunda cucharada de leche.","Use una cuchara para galletas PEQUEÑA, o una cucharada, para colocar porciones de masa en la bandeja, dejando bastante espacio entre cada una. Debería obtener entre 12 y 14 galletas. Use un tenedor para presionar suavemente cada galleta y ayudarlas a extenderse. Seguirán extendiéndose en el horno.","Hornee durante 10-11 minutos y retire del horno. Se sentirán blandas y poco cocidas; esto es normal, así que no intente comerlas directamente al sacarlas del horno. Déjelas reposar por lo menos 10 minutos antes de manipularlas. Luego páselas a una rejilla para que sigan enfriándose y terminen de firmarse."],
["Asegúrese de usar solo 1 cucharada de leche para empezar a mezclar la masa. Según la consistencia de su mantequilla de nueces, puede que necesite o no la segunda cucharada. Será tentador, pero no toque las galletas una vez que las saque del horno. Déjelas reposar 10 minutos antes de manipularlas, ya que estarán muy blandas y parecerán poco cocidas antes de enfriarse. Para menos azúcar, puede reducirla a ¼ de taza con resultados similares. Guarde las galletas a temperatura ambiente en un recipiente durante 2-3 días, o refrigérelas hasta por 1 semana. Puede congelarlas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9532392,"Sopa de miso con tomates asados","Una fantástica sopa de miso con tomate, hecha con solo seis ingredientes pero llena de sabor.","4 porciones","1 porción",
["2 libras de tomates maduros en la planta, cortados en cuartos","1 cebolla amarilla cortada en cuartos","6 dientes de ajo sin pelar","2 tazas de caldo de verduras bajo en sodio","¼ de taza de pasta de miso blanco","½ taza de frijoles cannellini blancos, cocidos o enlatados","sal + pimienta al gusto",("Para decorar","albahaca fresca o perejil"),("Para decorar","galletas saladas, crutones o pan crujiente")],
["Precaliente el horno a 425℉/218℃ en modo de convección y forre una bandeja grande para hornear con papel pergamino.","Coloque los tomates en cuartos, la cebolla y los dientes de ajo (no pele el ajo) en la bandeja y áselos durante 25 minutos, o hasta que las verduras estén doradas. Retire del horno.","Una vez asadas, pele el ajo (saldrá fácilmente de su piel) y agregue las verduras asadas, el caldo, la pasta de miso y los frijoles a una licuadora. Procese hasta que quede completamente suave. Pruebe y ajuste la sal y la pimienta, y sirva."],
["Use un caldo de verduras bajo en sodio, ya que la pasta de miso también aporta un sabor salado. Una vez licuada, pruebe y agregue sal y pimienta, si es necesario.","Si no tiene un horno de convección, use la misma temperatura, pero tenga en cuenta que puede necesitar unos 5 minutos adicionales para asar las verduras.","Las sobras se conservan refrigeradas de 3 a 4 días, o puede congelarlas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9537373,"Gajos de papa en freidora de aire","¿Listo para los gajos de papa más crujientes en freidora de aire? ¡Llenos de sabor, con poco esfuerzo y listos en 15 minutos!","2 porciones","1 porción",
["1 libra de papas russet, aprox. 2 grandes","1 cucharada de aceite de aguacate, opcional","½ cucharadita de ajo en polvo","½ cucharadita de romero seco triturado","½ cucharadita de perejil seco","½ cucharadita de sal marina"],
["Pele las papas o fróteles bien hasta limpiarlas, y luego córtelas en gajos. (Vea arriba las fotos del proceso, si lo necesita.)","Coloque los gajos de papa en un tazón y cúbralos con agua fría durante al menos 20 minutos. Luego escúrralos y séquelos con un paño de cocina limpio. Seque el tazón y vuelva a colocar los gajos dentro.","Agregue el aceite (si lo usa) y todos los condimentos, y mezcle para cubrir de manera uniforme. Luego pase los gajos sazonados a la canasta de la freidora en una sola capa, dejando un poco de espacio entre ellos. (Cocine por tandas, si es necesario.)","Cocine en la freidora de aire a 400 grados F durante 15 minutos, mezclando una vez a la mitad del tiempo. Sirva con salsa de tomate (ketchup), mayonesa picante o cualquiera de sus salsas favoritas."],
["Aunque es opcional, recomiendo remojar los gajos de papa crudos para que queden lo más crujientes posible. Especialmente no debe omitir este paso si decide no usar aceite. Esta receta se ha probado con y sin aceite. Los resultados son similares, pero la opción con aceite queda un poco más crujiente, como era de esperar. Cambie el sabor cada vez con una de mis mezclas de especias mencionadas arriba. Los gajos de papa saben mejor recién hechos, pero las sobras se conservan refrigeradas hasta por 3 días."],[]))
X.append(r(9539328,"Tofu pegajoso estilo asiático","Este tofu dulce, picante y pegajoso es crujiente por fuera y tierno por dentro. Este plato de inspiración asiática está lleno de sabor y es garantía de éxito.","4 porciones","1 porción",
[("Para el tofu","12 onzas (340 gramos) de tofu extra firme"),("Para el tofu","2 cucharadas de tamari bajo en sodio o salsa de soya baja en sodio si no evita el gluten"),("Para el tofu","2 cucharadas de harina de arroz integral"),("Para el tofu","1 cucharadita de cebolla en polvo"),("Para el tofu","1 cucharadita de ajo en polvo"),("Para la salsa del tofu pegajoso","⅓ de taza de tamari bajo en sodio o salsa de soya"),("Para la salsa del tofu pegajoso","⅓ de taza de azúcar de coco sin refinar o azúcar morena"),("Para la salsa del tofu pegajoso","⅓ de taza de agua"),("Para la salsa del tofu pegajoso","¼ de taza de vinagre de arroz"),("Para la salsa del tofu pegajoso","2 dientes de ajo picados finamente"),("Para la salsa del tofu pegajoso","1 cucharada de sriracha o salsa picante de su elección"),("Para la salsa del tofu pegajoso","½ cucharadita de jengibre molido"),("Para la salsa del tofu pegajoso","2 cucharadas de harina de arroz integral"),("Para servir (opcional)","fideos vermicelli o arroz integral"),("Para servir (opcional)","cebollín o cebollino"),("Para servir (opcional)","semillas de ajonjolí")],
[("Prense el tofu","Corte el tofu en cubos de media pulgada. Luego coloque servilletas de papel o un paño de cocina limpio sobre una tabla de cortar y ponga los cubos de tofu encima en una sola capa. Ahora agregue más servilletas de papel sobre los cubos y coloque encima otra tabla de cortar, un plato plano o una bandeja para hornear. Finalmente, ponga algo muy pesado encima, como una sartén de hierro fundido o un libro pesado. Presione así durante 15 minutos mientras prepara los demás ingredientes."),("Para el tofu","Precaliente el horno a 425°F/218°C en modo de convección y forre una bandeja para hornear con papel pergamino."),("Para el tofu","Una vez prensado el tofu, coloque los cubos en un tazón mediano con las 2 cucharadas de tamari y mezcle suavemente. Luego agregue las 2 cucharadas de harina y la cebolla y el ajo en polvo. Mezcle con cuidado para cubrir los trozos de manera uniforme."),("Para el tofu","Distribuya los cubos de tofu cubiertos en una sola capa sobre la bandeja, dejando bastante espacio entre cada pieza. Hornee durante 25-30 minutos, volteándolos una vez a la mitad del tiempo. NOTA: Si no tiene un horno de convección, puede tardar un poco más en alcanzar la textura crujiente deseada."),("Para la salsa del tofu pegajoso","Mientras se hornea el tofu, mezcle todos los ingredientes de la salsa en una sartén mediana. Bata para combinar y cocine a fuego lento durante 5 minutos, hasta que espese ligeramente. Luego apague el fuego."),("Para la salsa del tofu pegajoso","Agregue el tofu horneado a la sartén con la salsa y revuelva suavemente para cubrir cada pieza."),("Para la salsa del tofu pegajoso","Sirva el tofu pegajoso con arroz o fideos, y decore con cebollín o cebollino y semillas de ajonjolí.")],
["Distribuya los cubos de tofu en una sola capa, con espacio entre cada pieza. No deben tocarse en la bandeja para lograr la máxima crujiente. Si no tiene un horno de convección, puede tardar unos minutos más en quedar crujiente. Hornee hasta alcanzar el nivel de textura crujiente deseado. Para obtener la mejor textura, planee disfrutar su tofu pegajoso asiático de inmediato. Cuanto más tiempo permanezca en la salsa, más empezará a perder su exterior crujiente. Este plato de tofu pegajoso sabe mejor recién hecho. Sin embargo, las sobras se conservan refrigeradas en un recipiente sellado de 3 a 4 días. Para recalentarlas, agregue un chorrito de agua a la sartén con el tofu para aflojar la salsa."],[]))
X.append(r(9539871,"Waffles de plátano con proteína","Estos waffles de plátano con proteína, sin gluten, están llenos de sabor, endulzados naturalmente y contienen 8 gramos de proteína en un solo waffle pequeño.","8 waffles","1 porción",
["1 taza de plátano (banana) machacado, aprox. 3 plátanos grandes","⅓ de taza + 1 cucharada de leche de soya o leche vegetal de su elección","100 gramos de harina de almendra blanqueada, aprox. 1 taza","100 gramos de mantequilla de maní en polvo, aprox. 1 taza","2 cucharaditas de polvo para hornear","1 cucharadita de canela"],
["Precaliente la wafflera a fuego medio y engrásela si es necesario.","Machaque los plátanos por completo y mézclelos con la leche en un tazón mediano. Luego agregue los ingredientes secos y revuelva hasta que estén bien combinados.","Coloque la masa de los waffles con una cuchara en la wafflera precalentada y cocine según las instrucciones del fabricante de su marca de wafflera. A mí me tomó 3-4 minutos por tanda. Para revisar los waffles, levante la tapa lenta y suavemente para asegurarse de que no se estén pegando. Si se pegan, aún no están listos, así que continúe cocinando por un minuto más aproximadamente antes de volver a revisar.","Sirva los waffles de plátano con proteína con sus coberturas favoritas."],
["Pese la harina y el polvo para obtener los mejores resultados. Si los toma con cuchara directamente de la bolsa, puede terminar con demasiada cantidad y necesitar más líquido para lograr la consistencia correcta de la masa.","Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y use un cuchillo para nivelar el exceso.","Use plátanos muy maduros, con manchas marrones, para obtener el mejor sabor.","Asegúrese de que su wafflera esté CALIENTE antes de agregar la masa, para evitar que se pegue.","No levante la tapa demasiado pronto o los waffles se romperán; levante la tapa lenta y cuidadosamente para revisar si se pegan.","Las tandas siguientes de waffles se cocinan un poco más rápido que la primera, así que vigílelas de cerca.","Guarde las sobras en el refrigerador de 3 a 4 días o congeladas hasta por 3 meses."],[]))
X.append(r(9541318,"Fresas en freidora de aire","Las fresas en freidora de aire son un dulce completamente saludable, sin azúcar añadida.","2 porciones","1 porción",
["300 gramos de fresas frescas"],
["Lave las fresas y séquelas con toques para eliminar el exceso de humedad. Luego use un quitador de tallos para fresas o un cuchillo afilado para quitarles el cabito y los tallos.","Corte las fresas en rodajas lo más uniformes posible, de aprox. 1/8 de pulgada de grosor. Luego colóquelas en la canasta de la freidora de aire en una sola capa, sin que se superpongan.","Cocine en la freidora de aire o use la función de deshidratar (según su modelo) a 190℉/88℃ durante 60-90 minutos. (El tiempo variará según el grosor de las rodajas y el modelo de freidora de aire que tenga.)","Empiece a revisar las fresas a los 45 minutos y voltéelas. Luego siga revisándolas a intervalos de 15 minutos hasta que estén completamente secas al tacto.",("Instrucciones para el horno","Precaliente el horno a 200℉/93℃ y forre una bandeja para hornear con papel pergamino."),("Instrucciones para el horno","Lave las fresas y séquelas con toques para eliminar el exceso de humedad. Luego use un quitador de tallos para fresas o un cuchillo afilado para quitarles el cabito y los tallos."),("Instrucciones para el horno","Corte las fresas en rodajas lo más uniformes posible, de aprox. 1/8 de pulgada de grosor. Luego colóquelas en la bandeja para hornear en una sola capa, sin que se superpongan."),("Instrucciones para el horno","Hornee durante 90 minutos, y luego despegue las rodajas del papel pergamino y voltéelas. Continúe horneando otros 30-60 minutos hasta que estén completamente secas. (El grosor de las rodajas determinará cuánto tardan en secarse por completo.)")],
["Las rodajas gruesas tardarán más en secarse que las delgadas. Haga su mejor esfuerzo por cortar las fresas con un grosor uniforme para que los tiempos de cocción sean parejos.","Retire las piezas más delgadas cuando estén listas y continúe cocinando las más gruesas hasta que cada rodaja esté deshidratada.","Las he preparado con y sin papel pergamino en la canasta de la freidora de aire. Ambas opciones funcionan bien, pero"],[]))
X.append(r(9545277,"Crema vegana de pollo","La crema de \"pollo\" vegana casera es el máximo alimento reconfortante.","2 porciones","1 porción",
[("Para el caldo de pollo vegano","2 tazas de agua"),("Para el caldo de pollo vegano","4 cucharadas de levadura nutricional"),("Para el caldo de pollo vegano","1 ¼ cucharaditas de condimento para aves"),("Para el caldo de pollo vegano","¾ de cucharadita de cebolla en polvo"),("Para el caldo de pollo vegano","¾ de cucharadita de ajo en polvo"),("Para el caldo de pollo vegano","¼ de cucharadita de perejil seco"),("Para el caldo de pollo vegano","¼ de cucharadita de semillas de apio"),("Para el caldo de pollo vegano","½ cucharadita de sal marina o al gusto"),("Para el caldo de pollo vegano","⅛ de cucharadita de pimienta negra o al gusto"),("Para la crema vegana de pollo","½ taza de nueces de la India (anacardos) crudas o ¼ de taza de mantequilla de nuez de la India"),("Para la crema vegana de pollo","¼ de taza de leche de nuez de la India sin azúcar o la leche sin lácteos de su elección"),("Opcional, para servir","pimienta negra u hojuelas de chile rojo"),("Opcional, para servir","galletas saladas, crutones o pan crujiente")],
[("Para preparar en Vitamix","Agregue todos los ingredientes, excepto la leche sin lácteos, a su Vitamix u otra licuadora potente y licúe hasta que esté suave, cremoso y caliente. En mi Vitamix, la sopa tardó unos 4 minutos en calentarse. Luego vierta la leche, licúe unos segundos para incorporarla y sirva."),("Para preparar en la estufa","Si usa la opción de mantequilla de nuez de la India, no necesita una licuadora. Solo agregue todo, excepto la leche, a una cacerola mediana y bata para combinar. Lleve a hervor suave a fuego medio y hierva de 1 a 2 minutos. Luego apague el fuego, incorpore la leche sin lácteos y sirva.")],
["Licúe el tiempo suficiente para que la sopa quede lo bastante caliente para consumirse. Esto funciona bien con licuadoras de alta calidad, como una Vitamix. (enlace de afiliado) Si no tiene una licuadora potente, puede remojar las nueces de la India en agua caliente de 20 a 30 minutos y luego escurrirlas antes de licuar. Esto ayudará a que se descompongan con más facilidad. O use mantequilla de nuez de la India y bátala en una olla pequeña para evitar por completo el uso de licuadora. Para opciones bajas en grasa, vea arriba en nuestra sección de variaciones. Guarde las sobras en el refrigerador hasta por 4 días o congélelas en un recipiente hermético hasta por 6 meses."],[]))
X.append(r(9551453,"Sopa vegana de frijoles negros","Una sopa vegana de frijoles negros sustanciosa y llena de sabor, deliciosa y sencilla de preparar. Cubra con aguacate y limón para obtener el tazón reconfortante definitivo.","4 porciones","1 porción",
["1 cebolla amarilla (picada en cubos)","2 zanahorias (peladas + picadas en cubos)","3 dientes de ajo (picados finamente)","2 latas de 15 onzas de frijoles negros","3.5 tazas de caldo de verduras","1 taza de salsa de tomate","2 cucharaditas de comino","2 cucharaditas de pimentón ahumado","2 cucharaditas de orégano seco","1/2 cucharadita de pimienta de cayena (o al gusto)","sal + pimienta (al gusto)","jugo de limón recién exprimido (recomendado)","crema de nuez de la India","rodajas de aguacate"],
["Agregue la cebolla, las zanahorias y el ajo a una olla con 3 cucharadas de caldo o agua y saltee hasta que se ablanden, aprox. 5-6 minutos. Agregue un poco más de agua o caldo según sea necesario para evitar que se pegue.","Luego agregue todos los demás ingredientes y lleve a hervor a fuego alto. Una vez que hierva, reduzca el fuego para mantener un hervor suave y cocine de 12 a 15 minutos, hasta que las zanahorias estén tiernas.","Apague el fuego y use una licuadora de inmersión para hacer puré UNA PARTE de la sopa, dejando algo de textura. O, pase la mitad de la sopa a una licuadora de vaso, hágala puré y devuélvala a la olla con el resto de la sopa.","Sirva la sopa de frijoles negros con las guarniciones de su elección."],[],[]))
X.append(r(9552882,"Ensalada primaveral de quinua","Fresca, llena de sabor y de ingredientes de temporada, esta ensalada primaveral de quinua es perfecta para los días soleados.","6 porciones","1 porción",
["1 taza de quinua","2 tazas de caldo de verduras","1 manojo de espárragos (sin los extremos y cortados en trozos de 1 pulgada)","1 taza de guisantes congelados (descongelados)","1 taza de pepino (cortado en cuartos a lo largo y en rodajas)","1.5 tazas de garbanzos (aprox. 1 lata de 15 onzas)","1/4 de taza de albahaca fresca (picada)","2 cucharadas de tahini","3 cucharadas de vinagre de manzana (o jugo de limón)","1 cucharada de jarabe de arce (o endulzante líquido de su elección)","1 cucharadita de ajo en polvo","sal + pimienta (al gusto)"],
["Agregue la quinua y el caldo a una olla pequeña y lleve a ebullición. Luego reduzca el fuego y cocine a fuego lento de 12 a 15 minutos, hasta que se absorba el líquido. Esponje con un tenedor y reserve.","Mientras tanto, ase a la parrilla o saltee los trozos de espárrago y espolvoréelos con sal y pimienta. (Como alternativa, puede dejar los espárragos crudos para que queden más crujientes.)","Combine los ingredientes del aderezo para ensalada en un tazón pequeño y mezcle bien, probando la sal y la pimienta y ajustando a su gusto.","En un tazón grande, agregue la quinua cocida, los espárragos cocidos o crudos (a su elección), los guisantes, el pepino, la albahaca y el aderezo para ensalada. Mezcle bien y sirva de inmediato, o puede refrigerar durante 1 hora o más antes de servir."],[],[]))
X.append(r(9553231,"Bolitas energéticas de frambuesa","Estas bolitas energéticas de frambuesa están endulzadas naturalmente con dátiles y ofrecen una explosión de sabor frutal sin azúcar refinada.","24 bolitas","1 porción",
["1 taza de almendras blanqueadas o nueces de la India (anacardos) crudas","1 taza de avena en hojuelas","1 taza de frambuesas frescas","½ taza de dátiles sin hueso, bien compactados","1 cucharadita de extracto puro de vainilla"],
["Forre una bandeja con papel pergamino y reserve.","Agregue todos los ingredientes al tazón del procesador de alimentos. Pulse hasta que estén bien combinados, sin hacer un puré completo de la mezcla.","Use una cuchara pequeña para galletas o una cuchara para tomar porciones de la mezcla y formar bolitas. Coloque cada bolita en la bandeja forrada. OPCIONAL: Pase algunas de las bolitas por cacao en polvo o coco rallado.","Refrigere durante 1 hora o más para que se enfríen y se firmen. ¡Disfrute!"],
["No procese demasiado la mezcla, ya que estos bocadillos saben mejor con un poco de textura.","La masa es un poco pegajosa, así que use las manos húmedas para formar las bolitas y evitar que se peguen a las manos.","Las bolitas recién formadas estarán blandas, así que refrigérelas por lo menos 1 hora antes de disfrutarlas para que se endurezcan y se firmen.","Guarde las bolitas energéticas de frambuesa en el refrigerador hasta por 5 días. O congélelas hasta por 3 meses."],[]))
X.append(r(9556376,"Dip de aguacate y jalapeño","Un dip ácido, picante y cremoso listo en solo 10 minutos.","6 porciones","1 porción",
["3 aguacates maduros, pelados + sin hueso","1 frasco de 8.5 onzas (250 ml) de jalapeños en escabeche, con su jugo","½ taza de semillas de girasol crudas","1 cucharadita de ajo en polvo","1 cucharada de jugo de limón, opcional, para más acidez","sal + pimienta al gusto"],
["Agregue los aguacates, los jalapeños en escabeche con su jugo, las semillas de girasol y el ajo en polvo al tazón del procesador de alimentos y procese hasta que quede suave.","Pruebe la mezcla y agregue jugo de limón para más acidez y sal + pimienta si lo desea.","Disfrútelo con galletas saladas, totopos, chips de pan pita y palitos de verduras crudas."],
["Pruebe el dip antes de agregar el jugo de limón. Según la cantidad de líquido de escabeche que tenga su frasco de jalapeños, puede que necesite o desee más acidez, o no.","Las sobras se conservan en el refrigerador de 3 a 4 días en un recipiente hermético, o puede congelarlas hasta por 3 meses."],[]))
X.append(r(9557682,"Arroz con frijoles fácil","Un plato sustancioso, delicioso, saciante y rico en nutrientes que se prepara en una sola sartén. Esta receta fácil de arroz con frijoles es una que querrá incluir en su rotación de comidas.","5 porciones","1 porción",
["1 cucharada de aceite de aguacate (o use caldo para una versión sin aceite)","1 taza de arroz blanco de grano largo","1 cebolla amarilla pequeña (picada finamente)","3 dientes de ajo (pelados + picados finamente)","1 cucharadita de pimentón ahumado","1/2 cucharadita de comino","2 tazas de caldo de verduras","1 taza de salsa mediana extra con trozos (o la de su preferencia)","1 lata de 15 onzas de frijoles negros (escurridos + enjuagados)","cilantro o perejil fresco (para decorar)"],
["Enjuague el arroz para eliminar parte del exceso de almidón.","Precaliente una sartén grande o una sartén de hierro fundido en la estufa a fuego medio-alto. Luego agregue el aceite o el caldo, seguido del arroz. Tueste el arroz, revolviendo con frecuencia, hasta que esté dorado, aprox. 5-7 minutos.","Agregue la cebolla, el ajo, el comino y el pimentón ahumado a la sartén y saltee hasta que las verduras estén translúcidas y aromáticas, aprox. 2-3 minutos.","Ahora agregue el caldo y la salsa, revuelva y tape la sartén con una tapa. Baje el fuego para cocinar el arroz a fuego lento durante aprox. 15 minutos, o hasta que se absorba el caldo. (NO abra la tapa mientras hierve a fuego lento.)","Una vez cocido el arroz, agregue los frijoles, mezcle bien y decore con cilantro o perejil."],[],[]))
X.append(r(9558150,"La MEJOR lasaña vegana, en serio","¡Capas de pasta tierna, verduras a la parrilla como calabacín (zucchini) y champiñones, queso ricotta de nuez de la India (anacardo) y una sustanciosa salsa boloñesa con \"carne\" de nuez de Castilla que es una delicia!","12 porciones","1 porción",
[("Ingredientes del ricotta de nuez de la India","1.5 tazas de nueces de la India (anacardos) crudas"),("Ingredientes del ricotta de nuez de la India","1 cucharada de vinagre de manzana"),("Ingredientes del ricotta de nuez de la India","¼ de taza de levadura nutricional"),("Ingredientes del ricotta de nuez de la India","¼ de cucharadita de ajo en polvo"),("Ingredientes del ricotta de nuez de la India","1 cucharadita de sal marina"),("Ingredientes del ricotta de nuez de la India","½ taza de agua"),("Ingredientes del ricotta de nuez de la India","1 paquete de 5 onzas de espinacas baby, aprox. 3 puñados grandes (o 1 taza ya marchitas)"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","1 cucharadita de aceite de aguacate o saltee con agua o caldo para una versión sin aceite"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","220 gramos de champiñones cremini, aprox. 8 champiñones"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","1 taza de nueces de Castilla"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","½ taza de tomates secados al sol"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","6 tazas de salsa de tomate o puré de tomate de su elección"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","¼ de cucharadita de orégano seco"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","¼ de cucharadita de albahaca seca"),("Ingredientes de la salsa boloñesa de champiñones y nuez de Castilla","½ cucharadita de sal marina"),("Ingredientes de las verduras a la parrilla","2 champiñones portobello grandes, en rodajas"),("Ingredientes de las verduras a la parrilla","2 calabacines (zucchini) grandes, en rodajas"),("Ingredientes de las verduras a la parrilla","1 cucharada de aceite de aguacate o rocíe con agua o caldo para una versión sin aceite"),("Ingredientes de las verduras a la parrilla","Sal + pimienta al gusto"),("Ingredientes de las láminas de lasaña","1 paquete de 454 gramos de láminas de lasaña, integrales o sin gluten si lo prefiere (también puede usar láminas de lasaña listas para hornear/sin hervir para ahorrar tiempo)"),("Cobertura opcional pero recomendada","queso parmesano vegano")],
[("Instrucciones del ricotta de nuez de la India","Marchite las espinacas en una sartén con unas gotas de agua para empezar. Una vez marchitas, coloque las espinacas sobre un paño de cocina limpio y presione con servilletas de papel para exprimir el líquido. Debe escurrir la mayor cantidad posible de líquido de las espinacas."),("Instrucciones del ricotta de nuez de la India","Agregue las nueces de la India al procesador de alimentos junto con todos los demás ingredientes, EXCEPTO las espinacas. Procese hasta que quede suave. Esto tomará aprox. 1-2 minutos, raspando los lados cada 30 segundos aproximadamente. Luego agregue las espinacas y pulse una o dos veces para incorporarlas. NO procese demasiado las espinacas. No queremos hacerlas puré ni que el queso se vuelva verde. En cambio, debe ver trozos de espinaca por toda la mezcla. Vea las fotos del proceso arriba."),("Instrucciones del ricotta de nuez de la India","Pase el ricotta a un tazón pequeño y refrigere hasta que lo necesite. Se espesará un poco más en el refrigerador."),("Instrucciones de la salsa boloñesa de champiñones y nuez de Castilla","Agregue los champiñones al procesador de alimentos y procese hasta que estén finamente picados. Luego agregue el aceite y los champiñones a una cacerola grande u olla. Cocine los champiñones durante aprox. 3 minutos, hasta que se reduzcan ligeramente."),("Instrucciones de la salsa boloñesa de champiñones y nuez de Castilla","Mientras tanto, procese las nueces de Castilla y los tomates secados al sol en el procesador de alimentos hasta lograr una textura desmenuzable. Luego agréguelos a la olla con los champiñones. Revuelva y luego agregue la salsa de tomate y los condimentos y mezcle bien."),("Instrucciones de la salsa boloñesa de champiñones y nuez de Castilla","Cocine la salsa a fuego lento durante 20 minutos y luego reserve hasta el momento de usarla."),("Instrucciones de las verduras a la parrilla","Forre una bandeja grande para hornear con papel pergamino y ponga el horno en función de asar (broil) a temperatura alta."),("Instrucciones de las verduras a la parrilla","Distribuya las verduras en rodajas en una sola capa, rocíelas con el aceite de oliva y espolvoréelas con sal y pimienta. Áselas con el asador durante 4 minutos, hasta que estén ligeramente doradas y reducidas, vigilando con cuidado para que no se quemen."),("Instrucciones de las verduras a la parrilla","Retire del horno y reserve."),("Instrucciones de las láminas de lasaña","Lleve a ebullición una olla grande con agua con sal y llene un tazón grande con agua fría. Coloque el tazón de agua fría sobre la encimera lo más cerca posible de la olla de agua hirviendo."),("Instrucciones de las láminas de lasaña","Agregue aproximadamente la mitad del paquete de láminas de lasaña a la olla de agua hirviendo. No sobrecargue la olla. Cocine de 2 a 3 minutos hasta que se ablanden, o según las instrucciones del paquete. Con unas pinzas, pase con cuidado las láminas de lasaña ablandadas al baño de agua."),("Instrucciones de las láminas de lasaña","Repita con las láminas restantes."),("Instrucciones para armar y hornear","Precaliente el horno a 400 grados F. Usé una bandeja de vidrio que mide 11\"x15\" y armé mi lasaña en el siguiente orden:Salsa | Láminas | Salsa | Queso ricotta | Calabacín | Salsa | Láminas | Salsa | Queso ricotta | Champiñones | Láminas | Salsa | Queso parmesano (opcional)"),("Instrucciones para armar y hornear","Coloque una capa fina de salsa en su recipiente de vidrio para hornear. Luego agregue encima una capa de láminas de lasaña en una sola capa. Agregue más salsa sobre las láminas de lasaña y extiéndala con una brocha de silicona."),("Instrucciones para armar y hornear","Ahora agregue la mitad de la mezcla de queso ricotta sobre la salsa, usando un tenedor para ayudar a extenderla de manera uniforme. Luego cubra el queso con las rodajas de calabacín y agregue otra capa fina de salsa sobre el calabacín."),("Instrucciones para armar y hornear","Ahora agregue la segunda capa de láminas de lasaña, seguida de otra capa fina de salsa. Luego extienda el resto del queso ricotta encima."),("Instrucciones para armar y hornear","A continuación, agregue los champiñones en una sola capa, seguidos de la tercera capa de láminas. Vierta más salsa sobre las láminas, asegurándose de llegar a todas las esquinas para evitar que se peguen durante el horneado."),("Instrucciones para armar y hornear","Opcional: Espolvoree generosamente queso parmesano vegano encima, si lo usa. (¡Recomendado!)"),("Instrucciones para armar y hornear","Cubra la bandeja con papel pergamino y luego con papel de aluminio y hornee en el horno precalentado durante 45 minutos. Retire del horno, destape y deje reposar de 10 a 15 minutos antes de cortar en 12 porciones y servir. Decore cada porción de lasaña con más queso parmesano o chiles picantes.")],
["Prepare TODAS las capas en el orden indicado, dejando las láminas de lasaña para el FINAL. No cocine las láminas de lasaña hasta que esté listo para armar. No queremos que se peguen entre sí ni que se empapen demasiado y se rompan. (Ignore esto si usa láminas listas para hornear.) Si no tiene un procesador de alimentos potente, remoje previamente las nueces de la India en agua caliente de 30 a 60 minutos para ablandarlas y ayudar a que se licúen hasta quedar suaves. Luego escúrralas y prepare el ricotta de nuez de la India según las indicaciones. Exprima la mayor cantidad posible de humedad de las espinacas para evitar un ricotta de nuez de la India acuoso. No haga puré las espinacas. No queremos un ricotta verde; solo pulse para picarlas suavemente y distribuirlas. Asegúrese de no procesar demasiado los champiñones, las nueces de Castilla ni los tomates secados al sol. Queremos una buena textura sustanciosa para la mejor lasaña vegana. Para las láminas de lasaña, no las sobrecargue en la olla de agua hirviendo al precocinarlas. Además, asegúrese de pasar las láminas a un baño de agua inmediatamente después de que estén tiernas. O use láminas listas para hornear. Corte las láminas de lasaña, según sea necesario, para que encajen bien en su recipiente para hornear. Alterne la dirección de las tres capas de láminas de lasaña para que sea más fácil cortarla una vez horneada. Para mantener esta receta vegana, revise la etiqueta del paquete de lasaña para asegurarse de que no contenga huevo, ya que algunas láminas de lasaña secas pueden contenerlo. Las sobras se conservan refrigeradas hasta por 4 días."],[]))
save(1,X)
